    <?php if (!$invitations): ?><p class="mt-4 text-xs text-slate-500">No pending invitations.</p><?php else: ?><div class="mt-4 grid gap-3 sm:grid-cols-2"><?php foreach($invitations as $invite): ?><article class="flex items-center justify-between gap-3 rounded-xl border border-white/[.08] bg-black/10 p-4"><div><p class="text-sm font-black"><?= h($invite['team_name']) ?></p><p class="mt-1 text-[10px] text-slate-500">From <?= h($invite['inviter_name']) ?> · expires <?= h(date('d M',strtotime((string)$invite['expires_at'].' UTC'))) ?></p></div><div class="flex gap-2"><?php foreach(['accepted'=>'Accept','rejected'=>'Decline'] as $choice=>$label): ?><form method="post" action="<?= h(app_url('index.php?action=invitation-response')) ?>"><?= csrf_field() ?><input type="hidden" name="invitation_id" value="<?= h($invite['id']) ?>"><input type="hidden" name="choice" value="<?= h($choice) ?>"><button class="rounded-lg px-3 py-2 text-[10px] font-black <?= $choice==='accepted'?'bg-violet-500 text-white':'border border-white/10 text-slate-300' ?>"><?= h($label) ?></button></form><?php endforeach; ?></div></article><?php endforeach; ?></div><?php endif; ?>
